#include <format>
#include <iostream>

// Positional and same-typed: easy to write, easy to swap.
struct PidConfigLong {
  double kp;
  double ki;
  double kd;
  double output_limit;
};
[[nodiscard]] PidConfigLong make_pid_long(double kp, double ki, double kd, double output_limit) {
  return {kp, ki, kd, output_limit};
}

// A required field and three optional ones, each named at the call site.
struct PidConfig {
  double kp;
  double ki = 0.0;
  double kd = 0.0;
  double output_limit = 100.0;
};

int main() {
  // Meant: kp=2.5, ki=0.1, kd=0.05, limit=100. Two middle arguments swapped, and it still compiles.
  const PidConfigLong swapped = make_pid_long(2.5, 0.05, 0.1, 100.0);
  std::cout << std::format("long ctor:  kp {}, ki {}, kd {}\n", swapped.kp, swapped.ki, swapped.kd);

  const PidConfig named{.kp = 2.5, .ki = 0.1, .kd = 0.05};
  std::cout << std::format("designated: kp {}, ki {}, kd {}\n", named.kp, named.ki, named.kd);
}

