#include <format>
#include <iostream>

struct PidConfig {
  double kp;
  double ki = 0.0;
  double kd = 0.0;
  double output_limit = 100.0;
};

// The classic Builder: one setter per optional field, each returning *this, and a final build().
class PidConfigBuilder {
 public:
  explicit PidConfigBuilder(double kp) : config_{.kp = kp} {}
  PidConfigBuilder& ki(double value) {
    config_.ki = value;
    return *this;
  }
  PidConfigBuilder& kd(double value) {
    config_.kd = value;
    return *this;
  }
  PidConfigBuilder& output_limit(double value) {
    config_.output_limit = value;
    return *this;
  }
  [[nodiscard]] PidConfig build() const { return config_; }

 private:
  PidConfig config_;
};

int main() {
  const PidConfig built = PidConfigBuilder(2.5).ki(0.1).kd(0.05).build();
  const PidConfig named{.kp = 2.5, .ki = 0.1, .kd = 0.05};

  std::cout << std::format("builder:    kp {}, ki {}, kd {}, limit {}\n", built.kp, built.ki, built.kd,
                           built.output_limit);
  std::cout << std::format("designated: kp {}, ki {}, kd {}, limit {}\n", named.kp, named.ki, named.kd,
                           named.output_limit);
  std::cout << std::format("same values: {}\n", built.kp == named.kp && built.ki == named.ki &&
                                                    built.kd == named.kd &&
                                                    built.output_limit == named.output_limit);
}

