#include <format>
#include <iostream>
#include <stdexcept>

struct PidConfig {
  double kp;
  double ki = 0.0;
  double kd = 0.0;
  double output_limit = 100.0;
};

// Checks the one thing a missing-initializer warning cannot: whether a given value makes sense.
[[nodiscard]] PidConfig make_pid(PidConfig config) {
  if (config.kp <= 0.0) throw std::invalid_argument("kp must be positive");
  if (config.output_limit <= 0.0) throw std::invalid_argument("output_limit must be positive");
  return config;
}

int main() {
  // kp was given a value, so the compiler has nothing left to say. The value itself is nonsense.
  const PidConfig questionable{.kp = -5.0};
  std::cout << std::format("aggregate alone: kp {} compiles, no error raised\n", questionable.kp);

  try {
    const PidConfig checked = make_pid({.kp = -5.0});
    std::cout << std::format("unreachable: kp {}\n", checked.kp);
  } catch (const std::invalid_argument& e) {
    std::cout << std::format("make_pid caught it: {}\n", e.what());
  }

  const PidConfig good = make_pid({.kp = 2.5, .ki = 0.4});
  std::cout << std::format("a valid config: kp {}, ki {}\n", good.kp, good.ki);
}

#include <cstdint>
#include <format>
#include <iostream>
#include <stdexcept>
#include <string>
#include <utility>

// What a caller fills in. Two fields are required in spirit; three have sensible defaults.
struct ScenarioParams {
  std::int32_t robot_count;
  std::int32_t duration_s;
  std::int32_t obstacle_density_pct = 0;
  std::int64_t seed = 0;
  bool record_video = false;
};

// What the rest of the program uses. Reaching this type means the values were checked.
struct ScenarioConfig {
  std::int32_t robot_count;
  std::int32_t duration_s;
  std::int32_t obstacle_density_pct;
  std::int64_t seed;
  bool record_video;
};

[[nodiscard]] ScenarioConfig make_scenario(ScenarioParams params) {
  if (params.robot_count <= 0) throw std::invalid_argument("robot_count must be positive");
  if (params.duration_s <= 0) throw std::invalid_argument("duration_s must be positive");
  if (params.obstacle_density_pct < 0 || params.obstacle_density_pct > 100) {
    throw std::invalid_argument("obstacle_density_pct must be within 0 to 100");
  }
  return ScenarioConfig{.robot_count = params.robot_count,
                        .duration_s = params.duration_s,
                        .obstacle_density_pct = params.obstacle_density_pct,
                        .seed = params.seed,
                        .record_video = params.record_video};
}

// A fluent front end over the same check: required fields at construction, optional ones by name.
class ScenarioBuilder {
 public:
  ScenarioBuilder(std::int32_t robot_count, std::int32_t duration_s)
      : params_{.robot_count = robot_count, .duration_s = duration_s} {}
  ScenarioBuilder& obstacle_density_pct(std::int32_t value) {
    params_.obstacle_density_pct = value;
    return *this;
  }
  ScenarioBuilder& seed(std::int64_t value) {
    params_.seed = value;
    return *this;
  }
  ScenarioBuilder& record_video(bool value) {
    params_.record_video = value;
    return *this;
  }
  [[nodiscard]] ScenarioConfig build() const { return make_scenario(params_); }

 private:
  ScenarioParams params_;
};

[[nodiscard]] std::string shown(const ScenarioConfig& config) {
  return std::format("{} robots, {} s, {}% obstacles, seed {}, video {}", config.robot_count, config.duration_s,
                     config.obstacle_density_pct, config.seed, config.record_video);
}

int main() {
  const ScenarioConfig from_factory =
      make_scenario({.robot_count = 4, .duration_s = 120, .obstacle_density_pct = 15, .seed = 42});
  const ScenarioConfig from_builder = ScenarioBuilder(4, 120).obstacle_density_pct(15).seed(42).build();
  std::cout << std::format("factory: {}\n", shown(from_factory));
  std::cout << std::format("builder: {}\n", shown(from_builder));

  try {
    [[maybe_unused]] const ScenarioConfig bad =
        make_scenario({.robot_count = 4, .duration_s = 120, .obstacle_density_pct = 150});
  } catch (const std::invalid_argument& e) {
    std::cout << std::format("factory rejected it: {}\n", e.what());
  }
  try {
    [[maybe_unused]] const ScenarioConfig bad = ScenarioBuilder(4, 120).obstacle_density_pct(150).build();
  } catch (const std::invalid_argument& e) {
    std::cout << std::format("builder rejected it: {}\n", e.what());
  }
}

#include <cstdint>
#include <format>
#include <iostream>
#include <stdexcept>

struct ScenarioParams {
  std::int32_t robot_count;
  std::int32_t duration_s;
  std::int32_t obstacle_density_pct = 0;
};

struct ScenarioConfig {
  std::int32_t robot_count;
  std::int32_t duration_s;
  std::int32_t obstacle_density_pct;
};

[[nodiscard]] ScenarioConfig make_scenario(ScenarioParams params) {
  if (params.robot_count <= 0) throw std::invalid_argument("robot_count must be positive");
  if (params.duration_s <= 0) throw std::invalid_argument("duration_s must be positive");
  if (params.obstacle_density_pct < 0 || params.obstacle_density_pct > 100) {
    throw std::invalid_argument("obstacle_density_pct must be within 0 to 100");
  }
  return ScenarioConfig{.robot_count = params.robot_count,
                        .duration_s = params.duration_s,
                        .obstacle_density_pct = params.obstacle_density_pct};
}

int main() {
  // Bypasses make_scenario entirely: ScenarioConfig is a plain aggregate with public fields.
  const ScenarioConfig unchecked{.robot_count = -5, .duration_s = 120, .obstacle_density_pct = 15};
  std::cout << std::format("built directly, no validation ran: robot_count {}\n", unchecked.robot_count);
}
